e_robot_open_top_drawer\": {\n        \"env_name\": \"OpenTopDrawerCustomInScene-v0\",\n        \"scene_name\": \"dummy_drawer\",\n        \"robot\": \"google_robot_static\",\n        \"rgb_overlay_path\": \"/root/autodl-tmp/SimplerEnv/ManiSkill2_real2sim/data/real_inpainting/open_drawer_a0.png\",\n        \"control_freq\": 3, \"sim_freq\": 513, \"max_episode_steps\": 113,\n        \"robot_init_xs\": [0.644], \"robot_init_ys\": [-0.179],\n        \"robot_init_rpy\": [0.0, 0.0, -0.03], \"quat_center\": [0, 0, 0, 1],\n        \"obj_variation_mode\": \"xy\",\n        \"obj_init_x_range\": [0.0, 0.0, 1],\n        \"obj_init_y_range\": [0.0, 0.0, 1],\n        \"policy_setup\": \"google_robot\",\n        \"unnorm_key\": \"fractal20220817_data\",\n        \"enable_raytracing\": True,\n        \"additional_env_build_kwargs\": {\n            \"station_name\": \"mk_station_recolor\",\n            \"light_mode\": \"simple\",\n            \"disable_bad_material\": True,\n        },\n    },\n    \"widowx_spoon_on_towel\": {\n        \"env_name\": \"PutSpoonOnTableClothInScene-v0\",\n        \"scene_name\": \"bridge_table_1_v1\",\n        \"robot\": \"widowx\",\n        \"rgb_overlay_path\": \"/root/autodl-tmp/SimplerEnv/ManiSkill2_real2sim/data/real_inpainting/bridge_real_eval_1.png\",\n        \"control_freq\": 5, \"sim_freq\": 500, \"max_episode_steps\": 60,\n        \"robot_init_xs\": [0.147], \"robot_init_ys\": [0.028],\n        \"robot_init_rpy\": [0.0, 0.0, 0.0], \"quat_center\": [0, 0, 0, 1],\n        \"obj_variation_mode\": \"episode\",\n        \"obj_episode_range\": [0, 24],\n        \"policy_setup\": \"widowx_bridge\",\n        \"unnorm_key\": \"bridge_orig\",\n    },\n    \"widowx_put_eggplant_in_basket\": {\n        \"env_name\": \"PutEggplantInBasketScene-v0\",\n        \"scene_name\": \"bridge_table_1_v2\",\n        \"robot\": \"widowx_sink_camera_setup\",\n        \"rgb_overlay_path\": \"/root/autodl-tmp/SimplerEnv/ManiSkill2_real2sim/data/real_inpainting/bridge_sink.png\",\n        \"control_freq\": 5, \"sim_freq\": 500, \"max_episode_steps\": 120,\n        \"robot_init_xs\": [0.127], \"robot_init_ys\": [0.06],\n        \"robot_init_rpy\": [0.0, 0.0, 0.0], \"quat_center\": [0, 0, 0, 1],\n        \"obj_variation_mode\": \"episode\",\n        \"obj_episode_range\": [0, 24],\n        \"policy_setup\": \"widowx_bridge\",\n        \"unnorm_key\": \"bridge_orig\",\n    },\n}\n\n# ── Pruning Hooks ──\n\nclass RandomPruningHook:\n    \"\"\"Keep random subset of vision tokens.\"\"\"\n    def __init__(self, k_ratio=0.5):\n        self.k_ratio = k_ratio\n        self.logged = False\n\n    def __call__(self, module, input, output):\n        B, N, D = output.shape\n        keep = max(1, int(N * self.k_ratio))\n        indices = torch.randperm(N)[:keep].sort().values.to(output.device)\n        pruned = output[:, indices, :]\n        if not self.logged:\n            print(f\"[Pruning] random: {N} -> {keep} tokens (k={self.k_ratio})\", flush=True)\n            self.logged = True\n        return pruned\n\n\nclass L2NormPruningHook:\n    \"\"\"Keep top-k vision tokens ranked by L2 norm.\"\"\"\n    def __init__(self, k_ratio=0.5):\n        self.k_ratio = k_ratio\n        self.logged = False\n\n    def __call__(self, module, input, output):\n        B, N, D = output.shape\n        keep = max(1, int(N * self.k_ratio))\n        norms = torch.norm(output.float(), dim=-1)\n        _, indices = torch.topk(norms, keep, dim=-1)\n        indices = indices.sort(dim=-1).values\n        pruned = torch.gather(output, 1, indices.unsqueeze(-1).expand(-1, -1, D))\n        if not self.logged:\n            print(f\"[Pruning] l2norm: {N} -> {keep} tokens (k={self.k_ratio})\", flush=True)\n            self.logged = True\n        return pruned\n\n\nclass AttentionPruningHook:\n    \"\"\"Keep top-k vision tokens ranked by attention importance (2-layer probe).\"\"\"\n    def __init__(self, k_ratio, vla):\n        self.k_ratio = k_ratio\n        self.vla = vla\n        self.logged = False\n\n    def __call__(self, module, input, output):\n        import torch.nn.functional as F\n        B, N, D = output.shape\n        keep = max(1, int(N * self.k_ratio))\n        if keep >= N:\n            return output\n\n        lm = self.vla.language_model.model\n        position_ids = torch.arange(N, device=output.device).unsqueeze(0).expand(B, -1)\n        hidden = output\n        all_attn = []\n\n        with torch.no_grad():\n            for layer_idx in range(min(2, len(lm.layers))):\n                layer = lm.layers[layer_idx]\n                normed = layer.input_layernorm(hidden)\n                head_dim = layer.self_attn.head_dim\n                n_q_heads = layer.self_attn.num_heads\n                n_kv_heads = layer.self_attn.num_key_value_heads\n\n                q = layer.self_attn.q_proj(normed).view(B, N, n_q_heads, head_dim).transpose(1, 2)\n                k = layer.self_attn.k_proj(normed).view(B, N, n_kv_heads, head_dim).transpose(1, 2)\n                v = layer.self_attn.v_proj(normed).view(B, N, n_kv_heads, head_dim).transpose(1, 2)\n\n                cos, sin = lm.rotary_emb(v, position_ids)\n                from transformers.models.llama.modeling_llama import rotate_half\n                q_embed = (q * cos) + (rotate_half(q) * sin)\n                k_embed = (k * cos) + (rotate_half(k) * sin)\n\n                if n_kv_heads != n_q_heads:\n                    n_rep = n_q_heads // n_kv_heads\n                    k_embed = k_embed.repeat_interleave(n_rep, dim=1)\n                    v = v.repeat_interleave(n_rep, dim=1)\n\n                attn_weights = torch.matmul(q_embed, k_embed.transpose(-2, -1)) / math.sqrt(head_dim)\n                attn_weights = F.softmax(attn_weights, dim=-1, dtype=torch.float32)\n                all_attn.append(attn_weights)\n\n                attn_out = torch.matmul(attn_weights.to(v.dtype), v)\n                attn_out = attn_out.transpose(1, 2).reshape(B, N, n_q_heads * head_dim)\n                attn_out = layer.self_attn.o_proj(attn_out)\n                hidden = hidden + attn_out\n                normed2 = layer.post_attention_layernorm(hidden)\n                hidden = hidden + layer.mlp(normed2)\n\n        avg_attn = torch.stack(all_attn).mean(dim=0).mean(dim=1)\n        importance = avg_attn.sum(dim=1)\n        _, indices = torch.topk(importance, keep, dim=-1)\n        indices = indices.sort(dim=-1).values\n        pruned = torch.gather(output, 1, indices.unsqueeze(-1).expand(-1, -1, D))\n        if not self.logged:\n            print(f\"[Pruning] attention: {N} -> {keep} tokens (k={self.k_ratio})\", flush=True)\n            self.logged = True\n        return pruned\n\n# ── OpenVLA Policy Adapter ──\n\nclass OpenVLAPruningPolicy:\n    \"\"\"OpenVLA policy with configurable vision token pruning for SimplerEnv.\"\"\"\n\n    def __init__(self, model_path, prune_mode=\"none\", keep_ratio=1.0,\n                 device=\"cuda:0\", center_crop=False):\n        self.device = torch.device(device)\n        self.prune_mode = prune_mode\n        self.keep_ratio = keep_ratio\n        self.center_crop = center_crop\n        self.task_description = None\n        self.policy_setup = None\n        self.unnorm_key = None\n\n        print(f\"[*] Loading OpenVLA from: {model_path}\", flush=True)\n        config = OpenVLAConfig.from_pretrained(model_path)\n        self.vla = OpenVLAForActionPrediction.from_pretrained(\n            model_path, config=config,\n            torch_dtype=torch.bfloat16, low_cpu_mem_usage=True,\n        ).to(self.device)\n\n        stats_path = os.path.join(model_path, \"dataset_statistics.json\")\n        if os.path.isfile(stats_path):\n            with open(stats_path) as f:\n                self.vla.norm_stats = json.load(f)\n            print(f\"[*] norm_stats keys: {list(self.vla.norm_stats.keys())}\", flush=True)\n        else:\n            print(f\"[!] No dataset_statistics.json at {stats_path}\", flush=True)\n\n        self.vla.eval()\n\n        tokenizer = AutoTokenizer.from_pretrained(model_path)\n        image_processor = PrismaticImageProcessor.from_pretrained(model_path)\n        self.processor = PrismaticProcessor(\n            image_processor=image_processor, tokenizer=tokenizer\n        )\n        print(f\"[*] Model loaded, VRAM: {torch.cuda.max_memory_allocated(self.device)/1e9:.1f} GB\",\n              flush=True)\n\n        self.hook_handle = None\n        if prune_mode != \"none\":\n            if prune_mode == \"random\":\n                hook = RandomPruningHook(keep_ratio)\n            elif prune_mode == \"l2norm\":\n                hook = L2NormPruningHook(keep_ratio)\n            elif prune_mode == \"attention\":\n                hook = AttentionPruningHook(keep_ratio, self.vla)\n            else:\n                raise ValueError(f\"Unknown prune_mode: {prune_mode}\")\n            self.hook_handle = self.vla.projector.register_forward_hook(hook)\n            print(f\"[*] Pruning hook: {prune_mode}, k={keep_ratio}\", flush=True)\n\n    def configure_task(self, policy_setup, unnorm_key):\n        \"\"\"Set per-task configuration (robot type and action un-normalization key).\"\"\"\n        self.policy_setup = policy_setup\n        self.unnorm_key = unnorm_key\n\n    def reset(self, task_description):\n        \"\"\"Reset for a new episode.\"\"\"\n        self.task_description = task_description\n\n    def step(self, image, task_description=None):\n        \"\"\"Run one inference step.\n\n        Args:\n            image: (H, W, 3) uint8 numpy RGB from SimplerEnv.\n            task_description: language instruction.\n\n        Returns:\n            (raw_action_dict, action_dict) for SimplerEnv evaluator.\n        \"\"\"\n        if task_description is not None:\n            self.task_description = task_description\n\n        pil_image = Image.fromarray(image).convert(\"RGB\")\n        if self.center_crop:\n            pil_image = self._center_crop(pil_image)\n\n        prompt = f\"In: What action should the robot take to {self.task_description.lower()}?\\nOut:\"\n        inputs = self.processor(prompt, pil_image).to(self.device, dtype=torch.bfloat16)\n\n        with torch.no_grad():\n            action_7d = self.vla.predict_action(\n                **inputs, unnorm_key=self.unnorm_key, do_sample=False\n            )\n\n        return self._to_simpler_env_action(action_7d)\n\n    def _to_simpler_env_action(self, a):\n        \"\"\"Convert 7D OpenVLA output to SimplerEnv (raw_action, action) dicts.\"\"\"\n        from transforms3d.euler import euler2axangle as _e2a\n\n        raw = {\n            \"world_vector\": a[:3].astype(np.float64),\n            \"rotation_delta\": a[3:6].astype(np.float64),\n            \"gripper_closedness_action\": np.array([a[6]], dtype=np.float64),\n            \"terminate_episode\": np.array([0.0, 0.0, 0.0]),\n        }\n\n        action = {\"world_vector\": raw[\"world_vector\"].copy()}\n\n        if self.policy_setup == \"google_robot\":\n            action[\"rot_axangle\"] = raw[\"rotation_delta\"].copy()\n            action[\"gripper\"] = np.array([2.0 * a[6] - 1.0], dtype=np.float64)\n        elif self.policy_setup == \"widowx_bridge\":\n            roll, pitch, yaw = raw[\"rotation_delta\"]\n            ax, angle = _e2a(roll, pitch, yaw)\n            action[\"rot_axangle\"] = (ax * angle).astype(np.float64)\n            g = -(2.0 * a[6] - 1.0)\n            g = 2.0 * float(g > 0.0) - 1.0\n            action[\"gripper\"] = np.array([g], dtype=np.float64)\n        else:\n            raise ValueError(f\"Unknown policy_setup: {self.policy_setup}\")\n\n        action[\"terminate_episode\"] = raw[\"terminate_episode\"]\n        return raw, action\n\n    def _center_crop(self, image, crop_scale=0.9):\n        w, h = image.size\n        nw = int(w * math.sqrt(crop_scale))\n        nh = int(h * math.sqrt(crop_scale))\n        left, top = (w - nw) // 2, (h - nh) // 2\n        return image.crop((left, top, left + nw, top + nh)).resize((w, h), Image.LANCZOS)\n\n    def visualize_epoch(self, predicted_actions, images, save_path):\n        \"\"\"Placeholder for SimplerEnv evaluator compatibility.\"\"\"\n        pass\n\n# ── CLI ──\n\ndef parse_args():\n    p = argparse.ArgumentParser(description=\"SimplerEnv OpenVLA pruning eval\")\n    p.add_argument(\"--model_path\", type=str, default=\"/root/autodl-tmp/openvla-7b\")\n    p.add_argument(\"--task\", type=str, nargs=\"+\",\n                    default=[\"google_robot_pick_coke_can\"],\n                    choices=list(TASK_CONFIGS.keys()))\n    p.add_argument(\"--prune_mode\", type=str, default=\"none\",\n                    choices=[\"none\", \"random\", \"l2norm\", \"attention\"])\n    p.add_argument(\"--keep_ratio\", type=float, default=1.0)\n    p.add_argument(\"--gpu\", type=int, default=0)\n    p.add_argument(\"--seed\", type=int, default=42)\n    p.add_argument(\"--center_crop\", action=\"store_true\", default=False)\n    p.add_argument(\"--num_episodes\", type=int, default=None,\n                    help=\"Cap total episodes per task (None = use task default)\")\n    p.add_argument(\"--output_dir\", type=str,\n                    default=\"/root/autodl-tmp/importance_margin_vla_compress/eval_results\")\n    p.add_argument(\"--logging_dir\", type=str,\n                    default=\"/root/autodl-tmp/importance_margin_vla_compress/results_simplerenv\")\n    return p.parse_args()\n\n\ndef build_eval_args(task_cfg, cli_args):\n    \"\"\"Build the args namespace that maniskill2_evaluator expects.\"\"\"\n    from sapien.core import Pose\n    from transforms3d.euler import euler2quat\n\n    a = argparse.Namespace()\n    a.robot = task_cfg[\"robot\"]\n    a.policy_model = \"openvla\"\n    a.ckpt_path = cli_args.model_path\n    a.env_name = task_cfg[\"env_name\"]\n    a.scene_name = task_cfg[\"scene_name\"]\n    a.rgb_overlay_path = task_cfg[\"rgb_overlay_path\"]\n    a.control_freq = task_cfg[\"control_freq\"]\n    a.sim_freq = task_cfg[\"sim_freq\"]\n    a.max_episode_steps = task_cfg[\"max_episode_steps\"]\n    a.enable_raytracing = task_cfg.get(\"enable_raytracing\", False)\n    a.additional_env_build_kwargs = task_cfg.get(\"additional_env_build_kwargs\", {})\n    a.additional_env_save_tags = None\n    a.obs_camera_name = None\n    a.logging_dir = cli_args.logging_dir\n    a.policy_setup = task_cfg[\"policy_setup\"]\n\n    a.robot_init_xs = np.array(task_cfg[\"robot_init_xs\"])\n    a.robot_init_ys = np.array(task_cfg[\"robot_init_ys\"])\n    r, p, y = task_cfg[\"robot_init_rpy\"]\n    qc = task_cfg[\"quat_center\"]\n    a.robot_init_quats = [(Pose(q=euler2quat(r, p, y)) * Pose(q=qc)).q]\n\n    a.obj_variation_mode = task_cfg[\"obj_variation_mode\"]\n    if a.obj_variation_mode == \"xy\":\n        xr = list(task_cfg[\"obj_init_x_range\"])\n        yr = list(task_cfg[\"obj_init_y_range\"])\n        if cli_args.num_episodes is not None:\n            n = max(1, int(math.sqrt(cli_args.num_episodes)))\n            xr[2] = n\n            yr[2] = n\n        a.obj_init_xs = np.linspace(xr[0], xr[1], int(xr[2]))\n        a.obj_init_ys = np.linspace(yr[0], yr[1], int(yr[2]))\n    elif a.obj_variation_mode == \"episode\":\n        er = list(task_cfg[\"obj_episode_range\"])\n        if cli_args.num_episodes is not None:\n            er[1] = min(er[0] + cli_args.num_episodes, er[1])\n        a.obj_episode_range = er\n\n    return a\n\n\ndef main():\n    args = parse_args()\n    device = f\"cuda:{args.gpu}\"\n\n    np.random.seed(args.seed)\n    torch.manual_seed(args.seed)\n    torch.cuda.manual_seed_all(args.seed)\n\n    policy = OpenVLAPruningPolicy(\n        model_path=args.model_path,\n        prune_mode=args.prune_mode,\n        keep_ratio=args.keep_ratio,\n        device=device,\n        center_crop=args.center_crop,\n    )\n\n    all_results = {}\n\n    for task_name in args.task:\n        print(f\"\\n{'='*60}\\nTask: {task_name}\\n{'='*60}\", flush=True)\n        task_cfg = TASK_CONFIGS[task_name]\n\n        policy.configure_task(task_cfg[\"policy_setup\"], task_cfg[\"unnorm_key\"])\n        eval_args = build_eval_args(task_cfg, args)\n\n        t0 = time.time()\n        success_arr = maniskill2_evaluator(policy, eval_args)\n        elapsed = time.time() - t0\n\n        sr = float(np.mean(success_arr)) if success_arr else 0.0\n        print(f\"\\n[Result] {task_name}: {sr:.1%} ({sum(success_arr)}/{len(success_arr)}) \"\n              f\"in {elapsed:.0f}s\", flush=True)\n\n        all_results[task_name] = {\n            \"success_rate\": sr,\n            \"n_success\": int(sum(success_arr)),\n            \"n_total\": len(success_arr),\n            \"elapsed_s\": round(elapsed, 1),\n        }\n\n    result = {\n        \"config\": {\n            \"model\": \"openvla-7b\",\n            \"model_path\": args.model_path,\n            \"prune_mode\": args.prune_mode,\n            \"keep_ratio\": args.keep_ratio if args.prune_mode != \"none\" else None,\n            \"seed\": args.seed,\n            \"center_crop\": args.center_crop,\n        },\n        \"results\": all_results,\n    }\n\n    os.makedirs(args.output_dir, exist_ok=True)\n    tasks_str = \"_\".join(\n        t.replace(\"google_robot_\", \"gr_\").replace(\"widowx_\", \"wx_\")\n        for t in args.task\n    )\n    if args.prune_mode == \"none\":\n        fname = f\"simplerenv_{tasks_str}_baseline_seed{args.seed}.json\"\n    else:\n        k_str = str(args.keep_ratio).replace(\".\", \"\")\n        fname = f\"simplerenv_{tasks_str}_{args.prune_mode}_k{k_str}_seed{args.seed}.json\"\n\n    out_path = os.path.join(args.output_dir, fname)\n    with open(out_path, \"w\") as f:\n        json.dump(result, f, indent=2)\n    print(f\"\\n[*] Results saved: {out_path}\", flush=True)\n\n\nif __name__ == \"__main__\":\n    main()\nENDOFFILE\necho \"Written OK: $(wc -l /root/autodl-tmp/importance_margin_vla_compress/eval_openvla_pruning_simplerenv.py)\"","account":"root"},"caller":{"type":"direct"}}],"stop_r